create or replace function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.block_direct_quantity_update() returns trigger language plpgsql as $$ begin if new.quantity<>old.quantity and current_setting('app.inventory_rpc',true)<>'on' then raise exception 'quantity changes must use inventory movement'; end if; return new; end; $$;
create trigger product_variant_quantity_guard before update on public.product_variants for each row execute function public.block_direct_quantity_update();
create or replace function public.apply_inventory_movement(p_variant_id uuid,p_type public.inventory_movement_type,p_quantity integer,p_reference_id uuid default null,p_note text default null) returns public.product_variants language plpgsql security definer set search_path=public as $$ declare v public.product_variants;delta integer; begin if auth.uid() is null or public.current_role() not in('ADMIN','WAREHOUSE_MANAGER') then raise exception 'not authorized';end if;if p_quantity<=0 then raise exception 'quantity must be positive';end if;delta:=case when p_type in('stock_in','return') then p_quantity else -p_quantity end;perform set_config('app.inventory_rpc','on',true);update public.product_variants set quantity=quantity+delta,updated_at=now() where id=p_variant_id and quantity+delta>=0 returning * into v;if not found then raise exception 'insufficient stock or variant not found';end if;insert into public.inventory_movements(variant_id,type,quantity,reference_id,note,created_by) values(p_variant_id,p_type,p_quantity,p_reference_id,p_note,auth.uid());if v.quantity<=v.minimum_quantity then insert into public.notifications(type,title,message,metadata) values('LOW_STOCK','Low stock',format('SKU %s has %s units left',v.sku,v.quantity),jsonb_build_object('variant_id',v.id,'sku',v.sku,'quantity',v.quantity));end if;return v;end; $$;
grant execute on function public.apply_inventory_movement(uuid,public.inventory_movement_type,integer,uuid,text) to authenticated;